+
+  const renderTabs = ({
+    variantFlag,
+    perpsTabBadgeSeen = false,
+    perpsAvailable = true,
+    showTokens = true,
+    route,
+  }: {
+    variantFlag?: { name: string };
+    perpsTabBadgeSeen?: boolean;
+    perpsAvailable?: boolean;
+    showTokens?: boolean;
+    route?: string;
