+    const store = configureStore({
+      metamask: {
+        ...mockState.metamask,
+        enabledNetworkMap: { eip155: { [CHAIN_IDS.MAINNET]: true } },
+        perpsTabBadgeSeen,
+        remoteFeatureFlags: {
+          ...(perpsAvailable
+            ? {
+                perpsEnabledVersion: { enabled: true, minimumVersion: '0.0.0' },
