+        },
+      },
+    });
+
+    return renderWithProvider(
+      <MetaMetricsContext.Provider value={metaMetricsContext}>
+        <AccountOverviewTabs
+          showTokens={showTokens}
+          showNfts={false}
+          showActivity={false}
+          setBasicFunctionalityModalOpen={jest.fn()}
+          onSupportLinkClick={jest.fn()}
